# Missing aspects fall back to overview (matcher handles that).

EXP = "_These are expected outcomes from the project design, not measured production results._"

def L(url, text="Read the case study"):
    return f"\n\n[{text} →]({url})"

ENTITIES = []

def E(id, label, aliases, **answers):
    ENTITIES.append({"id": id, "label": label, "aliases": aliases, "answers": answers})

