def P(id, label, aliases, overview, problem, users, features, ai, outcomes, strategy, extra=None):
    d = dict(overview=overview, problem=problem, users=users, features=features, ai=ai,
             outcomes=outcomes + "\n\n" + EXP, strategy=strategy,
             role=f"Vishnu designed this through **ICD as design partner to UnifyApps**. Detailed timelines and team information for this project aren't public. For more, email him at vishnuprasadkp98@gmail.com.")
    if extra: d.update(extra)
    E(id, label, aliases, **d)

